const TYPES = ['', 'merchant_agreement', 'dpa', 'nda', 'vendor_agreement', 'receivables_purchase', 'collection_services', 'saas_agreement', 'amendment']

export default function Audits() {
  const { data: config } = usePolling(api.config, 0, () => false)
  const { data: audits, refresh } = usePolling(api.audits, 2000, (a) => !!a?.some((x) => x.status === 'running'))
  const [selected, setSelected] = useState<number | null>(null)
  const [kind, setKind] = useState('missing_clause')
  const [clauseType, setClauseType] = useState('liability_cap')
  const [passage, setPassage] = useState('')
  const [oldName, setOldName] = useState('')
  const [contractType, setContractType] = useState('')
  const [error, setError] = useState('')

  const run = async () => {
    const params: Record<string, string> = {}
    if (contractType) params.contract_type = contractType
    if (kind === 'missing_clause') params.clause_type = clauseType
    if (kind === 'missing_passage') params.passage = passage
    if (kind === 'rename' && oldName) params.old_name = oldName
    try {
      const a = await api.createAudit(kind, params)
      setSelected(a.id)
      setError('')
      refresh()
    } catch (e) {
      setError(String(e))
    }
  }

  return (
    <Stack spacing={2}>
      <Typography variant="h5">Audits</Typography>
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '340px 1fr' }, gap: 2, alignItems: 'start' }}>
        <Stack spacing={2}>
          <Paper sx={{ p: 2 }}>
            <Stack spacing={2}>
              <Typography variant="subtitle1">New audit</Typography>
              <TextField select size="small" label="Question" value={kind} onChange={(e) => setKind(e.target.value)}>
                {KINDS.map((k) => (
                  <MenuItem key={k.value} value={k.value}>
                    {k.label}
                  </MenuItem>
                ))}
              </TextField>
              {kind === 'missing_clause' && (
                <TextField select size="small" label="Clause type" value={clauseType} onChange={(e) => setClauseType(e.target.value)}>
                  {(config?.taxonomy ?? []).map((t) => (
                    <MenuItem key={t} value={t}>
                      {label(t)}
                    </MenuItem>
                  ))}
                </TextField>
              )}
              {kind === 'missing_passage' && (
                <TextField
                  size="small"
                  label="Passage (any wording)"
                  multiline
                  minRows={3}
                  value={passage}
                  onChange={(e) => setPassage(e.target.value)}
                  placeholder="Each Party shall comply with all applicable anti-corruption and anti-bribery laws…"
                />
              )}
              {kind === 'rename' && (
                <TextField
                  size="small"
                  label="Old name (blank = entity registry)"
                  value={oldName}
                  onChange={(e) => setOldName(e.target.value)}
                  helperText="Registry: arvato Financial Solutions, Arvato Payment Solutions GmbH, AFS → Riverty GmbH"
                />
              )}
              <TextField select size="small" label="Contract type" value={contractType} onChange={(e) => setContractType(e.target.value)}>
                {TYPES.map((t) => (
                  <MenuItem key={t} value={t}>
                    {t ? label(t) : 'All types'}
                  </MenuItem>
                ))}
              </TextField>
              <Button variant="contained" onClick={run}>
                Run audit
              </Button>
              {error && <Alert severity="error">{error}</Alert>}
            </Stack>
          </Paper>
          <Paper>
            <List dense disablePadding>
              {(audits ?? []).map((a) => (
                <ListItemButton key={a.id} selected={a.id === selected} onClick={() => setSelected(a.id)}>
                  <ListItemText
                    primary={`#${a.id} ${label(a.kind)}${a.params.clause_type ? ` · ${label(a.params.clause_type)}` : ''}`}
                    secondary={`${a.params.contract_type ? label(a.params.contract_type) : 'all types'} · ${summarize(a)}`}
                  />
                  <Chip size="small" label={a.status} color={a.status === 'done' ? 'success' : a.status === 'failed' ? 'error' : 'warning'} />
                </ListItemButton>
              ))}
            </List>
          </Paper>
        </Stack>
        {selected !== null ? <AuditDetail id={selected} /> : <Alert severity="info">Run an audit or pick one from the list.</Alert>}
      </Box>
    </Stack>
  )
}

function summarize(a: Audit) {
  const s = a.summary as Record<string, number>
  if (!s || a.status !== 'done') return typeof a.findings === 'number' ? `${a.findings} findings` : ''
  return `${s.scope} in scope · ${s.missing ?? 0} flagged · ${s.uncertain ?? 0} uncertain · ${s.unreadable ?? 0} unreadable`
}

function AuditDetail({ id }: { id: number }) {
  const { data: audit } = usePolling(() => api.audit(id), 1500, (a) => !a || a.status === 'running')
  const [open, setOpen] = useState<number | null>(null)
  if (!audit) return null
  const findings = audit.findings as Finding[]
  const s = audit.summary as Record<string, number | boolean | string>
  return (
    <Stack spacing={2}>
      <Paper sx={{ p: 2 }}>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
          <Typography variant="subtitle1" sx={{ mr: 1 }}>
            Audit #{audit.id} · {label(audit.kind)}
          </Typography>
          {Object.entries(audit.params).map(([k, v]) => (
            <Chip key={k} size="small" variant="outlined" label={`${label(k)}: ${label(String(v)).slice(0, 60)}`} />
          ))}
          {audit.status === 'done' && (
            <Chip
              size="small"
              color={s.verified ? 'success' : 'warning'}
              label={s.verified ? `verified by ${s.verifier}` : 'unverified – no verifier offline'}
            />
          )}
        </Stack>
        {audit.status === 'done' && (
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            {String(s.scope)} contracts in scope · {String(s.present)} clearly fine · {String(s.missing)} flagged · {String(s.uncertain)} uncertain
            {Number(s.historical_only) > 0 ? ` · ${s.historical_only} historical reference only` : ''}
            {Number(s.unreadable) > 0 ? ` · ${s.unreadable} unreadable (needs vision OCR)` : ''}
          </Typography>
        )}
        {audit.status === 'failed' && <Alert severity="error">{String(s.error)}</Alert>}
      </Paper>
      <Paper>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell width={32} />
              <TableCell>Contract</TableCell>
              <TableCell>Verdict</TableCell>
              <TableCell>Confidence</TableCell>
              <TableCell>Evidence</TableCell>
              <TableCell>Review</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {findings.map((f) => (
              <FindingRow key={f.id} f={f} open={open === f.id} toggle={() => setOpen(open === f.id ? null : f.id)} />
            ))}
            {audit.status === 'done' && findings.length === 0 && (
              <TableRow>
                <TableCell colSpan={6}>
                  <Typography color="text.secondary" sx={{ py: 2, textAlign: 'center' }}>
                    Nothing flagged — every contract in scope passed.
                  </Typography>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </Paper>
    </Stack>
  )
}

function FindingRow({ f, open, toggle }: { f: Finding; open: boolean; toggle: () => void }) {
  const first = f.evidence[0]
  return (
    <>
      <TableRow hover onClick={toggle} sx={{ cursor: 'pointer', '& td': { borderBottom: open ? 0 : undefined } }}>
        <TableCell>
          <IconButton size="small">{open ? <ExpandLessIcon /> : <ExpandMoreIcon />}</IconButton>
        </TableCell>
        <TableCell>
          <Typography variant="body2">{f.title}</Typography>
          <Typography variant="caption" color="text.secondary">
            {f.filename}
          </Typography>
        </TableCell>
        <TableCell>
          <VerdictChip verdict={f.verdict} />
        </TableCell>
        <TableCell>
          <Confidence value={f.confidence} />
        </TableCell>
        <TableCell sx={{ maxWidth: 380 }}>
          {first ? (
            <Typography variant="caption" noWrap display="block">
              p.{first.page}: {first.quote}
            </Typography>
          ) : (
            <Typography variant="caption" color="text.secondary">
              {f.method_chain[0]}
            </Typography>
          )}
        </TableCell>
        <TableCell>
          <ReviewChip status={f.review_status} />
        </TableCell>
      </TableRow>
      <TableRow>
        <TableCell colSpan={6} sx={{ py: 0 }}>
          <Collapse in={open} unmountOnExit>
            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' }, gap: 2, py: 2 }}>
              <Box>
                <Typography variant="subtitle2" gutterBottom>
                  How this finding was produced
                </Typography>
                <MethodTrace steps={f.method_chain} />
                {f.reasoning && (
                  <Typography variant="body2" sx={{ mt: 1.5 }}>
                    <strong>Verifier:</strong> {f.reasoning}
                  </Typography>
                )}
              </Box>
              <Box>
                <Typography variant="subtitle2" gutterBottom>
                  Evidence
                </Typography>
                {f.evidence.map((e, i) => (
                  <Quote key={i} page={e.page} quote={e.quote} />
                ))}
                {f.evidence.length === 0 && (
                  <Typography variant="body2" color="text.secondary">
                    No passage to quote — the page could not be read reliably.
                  </Typography>
                )}
              </Box>
            </Box>
          </Collapse>
        </TableCell>
      </TableRow>
    </>
  )
}

import { useState } from 'react'
import Alert from '@mui/material/Alert'
import Button from '@mui/material/Button'
import Chip from '@mui/material/Chip'
import CircularProgress from '@mui/material/CircularProgress'
import Paper from '@mui/material/Paper'
import Stack from '@mui/material/Stack'
import TextField from '@mui/material/TextField'
import Typography from '@mui/material/Typography'
import { api, label, type ChatResult } from '../api'
import { Quote } from '../components/ui'

const EXAMPLES = [
  'Which court has jurisdiction in the Nordlicht agreement?',
  'Welche Kündigungsfrist gilt im Inkassovertrag mit Rheinland Energie?',
  'What liability cap applies in the Lumen Retail merchant agreement?',
]

export default function Ask() {
  const [question, setQuestion] = useState('')
  const [result, setResult] = useState<ChatResult | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const ask = async (q: string) => {
    setQuestion(q)
    setLoading(true)
    try {
      setResult(await api.chat(q))
      setError('')
    } catch (e) {
      setError(String(e))
    }
    setLoading(false)
  }

  return (
    <Stack spacing={2} sx={{ maxWidth: 900 }}>
      <Typography variant="h5">Ask the contracts</Typography>
      <Typography variant="body2" color="text.secondary">
        Hybrid retrieval (full-text + vector, fused) over clauses, then an answer that must cite. Uncited statements are not allowed; if
        the passages do not answer the question, the model says so.
      </Typography>
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
        {EXAMPLES.map((e) => (
          <Chip key={e} label={e} variant="outlined" onClick={() => ask(e)} />
        ))}
      </Stack>
      <Stack direction="row" spacing={1}>
        <TextField fullWidth size="small" value={question} onChange={(e) => setQuestion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && ask(question)} placeholder="Ask in English or German…" />
        <Button variant="contained" onClick={() => ask(question)} disabled={!question || loading}>
          {loading ? <CircularProgress size={20} color="inherit" /> : 'Ask'}
        </Button>
      </Stack>
      {error && <Alert severity="error">{error}</Alert>}
      {result && (
        <>
          <Paper sx={{ p: 2 }}>
            <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
              <Typography variant="subtitle1">Answer</Typography>
              <Chip size="small" label={result.mode === 'llm' ? 'Gemini, cited' : 'offline: extractive'} color={result.mode === 'llm' ? 'success' : 'default'} />
            </Stack>
            <Typography variant="body1" sx={{ whiteSpace: 'pre-wrap' }}>
              {result.answer}
            </Typography>
            {result.citations.length > 0 && (
              <Stack spacing={0.5} sx={{ mt: 2 }}>
                <Typography variant="subtitle2">Citations</Typography>
                {result.citations.map((c, i) => (
                  <Stack key={i} direction="row" spacing={1} alignItems="flex-start">
                    <Chip size="small" label={`${c.title} · p.${c.page}`} />
                    <Typography variant="body2" sx={{ fontStyle: 'italic' }}>
                      “{c.quote}”
                    </Typography>
                  </Stack>
                ))}
              </Stack>
            )}
          </Paper>
          <Paper sx={{ p: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Retrieved passages
            </Typography>
            {result.passages.map((p) => (
              <Stack key={p.index} sx={{ mb: 1 }}>
                <Typography variant="caption" color="text.secondary">
                  [{p.index}] {p.title} · {label(p.clause_type)} · score {p.score}
                </Typography>
                <Quote page={p.page} quote={p.text.slice(0, 280)} />
              </Stack>
            ))}
          </Paper>
        </>
      )}
    </Stack>
  )
}

# Production shape on Azure. Not applied for the case study - it documents the infrastructure story:
#   - documents stay in the tenant: SharePoint (source) -> Blob (working copies) -> PostgreSQL/pgvector (index)
#   - the API and web containers run on Container Apps behind Entra ID
#   - OCR and models: Azure AI Document Intelligence for scans; LLM access through Foundry or
#     Gemini on Vertex AI (europe-west3), configured by variable, key held in Key Vault
#   - everything logs to Log Analytics; the append-only audit log lives in PostgreSQL

terraform {
  required_version = ">= 1.6"
  required_providers {
    azurerm = { source = "hashicorp/azurerm", version = "~> 4.0" }
  }
}

provider "azurerm" {
  features {}
}

locals {
  name = "${var.project}-${var.environment}"
  tags = { project = var.project, environment = var.environment, owner = "legal-tech" }
}

resource "azurerm_resource_group" "rg" {
  name     = "rg-${local.name}"
  location = var.location
  tags     = local.tags
}

# ---------------------------------------------------------------- observability
resource "azurerm_log_analytics_workspace" "logs" {
  name                = "log-${local.name}"
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name
  sku                 = "PerGB2018"
  retention_in_days   = 90
  tags                = local.tags
}

# ---------------------------------------------------------------- secrets
resource "azurerm_key_vault" "kv" {
  name                       = "kv-${replace(local.name, "-", "")}"
  location                   = azurerm_resource_group.rg.location
  resource_group_name        = azurerm_resource_group.rg.name
  tenant_id                  = var.tenant_id
  sku_name                   = "standard"
  purge_protection_enabled   = true
  soft_delete_retention_days = 90
  rbac_authorization_enabled = true
  tags                       = local.tags
}

# ---------------------------------------------------------------- documents (working copies; SharePoint stays the source)
resource "azurerm_storage_account" "docs" {
  name                            = "st${replace(local.name, "-", "")}"
  resource_group_name             = azurerm_resource_group.rg.name
  location                        = azurerm_resource_group.rg.location
  account_tier                    = "Standard"
  account_replication_type        = "ZRS"
  allow_nested_items_to_be_public = false
  min_tls_version                 = "TLS1_2"
  blob_properties {
    versioning_enabled = true
    delete_retention_policy { days = 30 }
  }
  tags = local.tags
}

resource "azurerm_storage_container" "contracts" {
  name                  = "contracts"
  storage_account_id    = azurerm_storage_account.docs.id
  container_access_type = "private"
}

# ---------------------------------------------------------------- index: PostgreSQL with pgvector
resource "azurerm_postgresql_flexible_server" "db" {
  name                          = "psql-${local.name}"
  resource_group_name           = azurerm_resource_group.rg.name
  location                      = azurerm_resource_group.rg.location
  version                       = "16"
  administrator_login           = "contracts"
  administrator_password        = var.db_password
  sku_name                      = var.db_sku
  storage_mb                    = 65536
  backup_retention_days         = 35
  geo_redundant_backup_enabled  = true
  public_network_access_enabled = false
  tags                          = local.tags
}

resource "azurerm_postgresql_flexible_server_configuration" "extensions" {
  name      = "azure.extensions"
  server_id = azurerm_postgresql_flexible_server.db.id
  value     = "VECTOR"
}

resource "azurerm_postgresql_flexible_server_database" "contracts" {
  name      = "contracts"
  server_id = azurerm_postgresql_flexible_server.db.id
  charset   = "UTF8"
  collation = "en_US.utf8"
}

# ---------------------------------------------------------------- OCR for scans (production path for Tesseract's role)
resource "azurerm_cognitive_account" "document_intelligence" {
  name                  = "di-${local.name}"
  location              = azurerm_resource_group.rg.location
  resource_group_name   = azurerm_resource_group.rg.name
  kind                  = "FormRecognizer"
  sku_name              = "S0"
  custom_subdomain_name = "di-${local.name}"
  tags                  = local.tags
}

# ---------------------------------------------------------------- compute
resource "azurerm_container_app_environment" "env" {
  name                       = "cae-${local.name}"
  location                   = azurerm_resource_group.rg.location
  resource_group_name        = azurerm_resource_group.rg.name
  log_analytics_workspace_id = azurerm_log_analytics_workspace.logs.id
  tags                       = local.tags
}

resource "azurerm_user_assigned_identity" "api" {
  name                = "id-${local.name}-api"
  location            = azurerm_resource_group.rg.location
  resource_group_name = azurerm_resource_group.rg.name
}

resource "azurerm_role_assignment" "api_secrets" {
  scope                = azurerm_key_vault.kv.id
  role_definition_name = "Key Vault Secrets User"
  principal_id         = azurerm_user_assigned_identity.api.principal_id
}

resource "azurerm_role_assignment" "api_blob" {
  scope                = azurerm_storage_account.docs.id
  role_definition_name = "Storage Blob Data Contributor"
  principal_id         = azurerm_user_assigned_identity.api.principal_id
}

resource "azurerm_container_app" "api" {
  name                         = "ca-${local.name}-api"
  container_app_environment_id = azurerm_container_app_environment.env.id
  resource_group_name          = azurerm_resource_group.rg.name
  revision_mode                = "Single"
  tags                         = local.tags

  identity {
    type         = "UserAssigned"
    identity_ids = [azurerm_user_assigned_identity.api.id]
  }

  secret {
    name                = "llm-api-key"
    key_vault_secret_id = "${azurerm_key_vault.kv.vault_uri}secrets/llm-api-key"
    identity            = azurerm_user_assigned_identity.api.id
  }
  secret {
    name                = "database-url"
    key_vault_secret_id = "${azurerm_key_vault.kv.vault_uri}secrets/database-url"
    identity            = azurerm_user_assigned_identity.api.id
  }

  template {
    min_replicas = 1
    max_replicas = 5
    container {
      name   = "api"
      image  = "${var.container_registry}/contract-intelligence-api:${var.image_tag}"
      cpu    = 1.0
      memory = "2Gi"
      env {
        name        = "GEMINI_API_KEY"
        secret_name = "llm-api-key"
      }
      env {
        name        = "DATABASE_URL"
        secret_name = "database-url"
      }
      env {
        name  = "LLM_PROVIDER"
        value = var.llm_provider
      }
      env {
        name  = "DOCUMENT_INTELLIGENCE_ENDPOINT"
        value = azurerm_cognitive_account.document_intelligence.endpoint
      }
    }
  }

  ingress {
    external_enabled = false # only the web app and internal callers reach the API
    target_port      = 8000
    traffic_weight {
      latest_revision = true
      percentage      = 100
    }
  }
}

resource "azurerm_container_app" "web" {
  name                         = "ca-${local.name}-web"
  container_app_environment_id = azurerm_container_app_environment.env.id
  resource_group_name          = azurerm_resource_group.rg.name
  revision_mode                = "Single"
  tags                         = local.tags

  template {
    min_replicas = 1
    max_replicas = 3
    container {
      name   = "web"
      image  = "${var.container_registry}/contract-intelligence-web:${var.image_tag}"
      cpu    = 0.25
      memory = "0.5Gi"
    }
  }

  ingress {
    external_enabled = true
    target_port      = 80
    traffic_weight {
      latest_revision = true
      percentage      = 100
    }
  }
}

# Entra ID sign-in in front of the web app: only members of the legal group get in.
resource "azurerm_container_app_auth" "web_sso" {
  count            = var.entra_client_id == "" ? 0 : 1
  container_app_id = azurerm_container_app.web.id
  unauthenticated_action = "RedirectToLoginPage"
  azure_active_directory {
    client_id     = var.entra_client_id
    tenant_id     = var.tenant_id
    allowed_groups = [var.legal_group_object_id]
  }
}

variable "project" {
  default = "contractintel"
}

variable "environment" {
  default = "dev"
}

variable "location" {
  description = "EU region: documents and the index never leave the tenant's region."
  default     = "germanywestcentral"
}

variable "tenant_id" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "db_sku" {
  default = "GP_Standard_D2ds_v5"
}

variable "container_registry" {
  description = "ACR login server hosting the two images."
  type        = string
}

variable "image_tag" {
  default = "latest"
}

variable "llm_provider" {
  description = "Where model calls go: 'foundry' (Azure AI Foundry) or 'gemini' (Vertex AI, europe-west3). Both keep data in the EU."
  default     = "gemini"
}

variable "entra_client_id" {
  description = "App registration used for Entra ID sign-in; empty disables SSO (dev only)."
  default     = ""
}

variable "legal_group_object_id" {
  description = "Entra ID group allowed to use the tool."
  default     = ""
}

output "web_url" {
  value = "https://${azurerm_container_app.web.ingress[0].fqdn}"
}

output "postgres_fqdn" {
  value = azurerm_postgresql_flexible_server.db.fqdn
}

output "document_intelligence_endpoint" {
  value = azurerm_cognitive_account.document_intelligence.endpoint
}

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'

export type Lang = 'de' | 'en'
export type Dict = Record<string, { de: string; en: string }>

type Settings = {
  lang: Lang
  setLang: (l: Lang) => void
  tech: boolean // global "show technical details" switch, off by default
  setTech: (t: boolean) => void
}

const Ctx = createContext<Settings>({ lang: 'de', setLang: () => {}, tech: false, setTech: () => {} })

function stored(key: string, fallback: string): string {
  try {
    return localStorage.getItem(key) ?? fallback
  } catch {
    return fallback
  }
}

export function SettingsProvider({ children }: { children: ReactNode }) {
  const [lang, setLang] = useState<Lang>(stored('lang', 'de') === 'en' ? 'en' : 'de')
  const [tech, setTech] = useState(stored('tech', '0') === '1')
  useEffect(() => {
    try {
      localStorage.setItem('lang', lang)
      localStorage.setItem('tech', tech ? '1' : '0')
    } catch {
      /* private mode etc. */
    }
    document.documentElement.lang = lang
  }, [lang, tech])
  return <Ctx.Provider value={{ lang, setLang, tech, setTech }}>{children}</Ctx.Provider>
}

export const useSettings = () => useContext(Ctx)

/** `const t = useT(DICT)` → `t('key', { n: 3 })`; `{n}` placeholders are interpolated. */
export function useT<D extends Dict>(dict: D) {
  const { lang } = useSettings()
  return (key: keyof D, vars?: Record<string, string | number>): string => {
    let s = dict[key]?.[lang] ?? String(key)
    for (const [k, v] of Object.entries(vars ?? {})) s = s.replaceAll(`{${k}}`, String(v))
    return s
  }
}

/** Translate a backend enum value (clause type, verdict, …) through a lookup; falls back to the raw value. */
export function useLabel(map: Record<string, { de: string; en: string }>) {
  const { lang } = useSettings()
  return (value: string): string => map[value]?.[lang] ?? value.replace(/_/g, ' ')
}

import { useState, type ReactNode } from 'react'
import Box from '@mui/material/Box'
import Collapse from '@mui/material/Collapse'
import Link from '@mui/material/Link'
import Typography from '@mui/material/Typography'
import { useSettings, useT } from '../i18n'

/** Renders its children only when the global "show technical details" switch is on. */
export function Tech({ children }: { children: ReactNode }) {
  const { tech } = useSettings()
  return tech ? <>{children}</> : null
}

/** Small grey print for secondary/technical information that stays visible. */
export function Small({ children, sx }: { children: ReactNode; sx?: object }) {
  return (
    <Typography variant="caption" component="div" sx={{ color: 'text.secondary', fontSize: 11.5, lineHeight: 1.4, ...sx }}>
      {children}
    </Typography>
  )
}

const T = {
  show: { de: 'Details anzeigen', en: 'Show details' },
  hide: { de: 'Details ausblenden', en: 'Hide details' },
}

/** A collapsed disclosure ("Details anzeigen") for the technical substance behind a result. */
export function Details({ children, label }: { children: ReactNode; label?: string }) {
  const t = useT(T)
  const [open, setOpen] = useState(false)
  return (
    <Box>
      <Link component="button" type="button" variant="caption" underline="hover" onClick={() => setOpen(!open)} sx={{ color: 'text.secondary' }}>
        {open ? t('hide') : (label ?? t('show'))}
      </Link>
      <Collapse in={open} unmountOnExit>
        <Box sx={{ mt: 1, p: 1.5, bgcolor: 'grey.50', borderRadius: 1, fontSize: 12 }}>{children}</Box>
      </Collapse>
    </Box>
  )
}

